declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';$db=db();$u=$db->query("SELECT id FROM users WHERE status='active' ORDER BY id LIMIT 1")->fetch_assoc();if(!$u)exit("No active student; schema-only check.\n");$db->begin_transaction();$id=(int)$u['id'];record_student_activity($id,'lesson_opened','Real-time alert verification');$s=$db->prepare("SELECT event_type,detail FROM student_activity_events WHERE user_id=? ORDER BY id DESC LIMIT 1");$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();$db->rollback();if(!$row||$row['detail']!=='Real-time alert verification'){fwrite(STDERR,"FAILED: event was not recorded.\n");exit(1);}echo "PASS: student activity is recorded and available to the live parent alert stream.\n";
